// Package aggregation owns bounded, layer-by-layer derived-memory generation.
// The model only writes the derived body; targets, titles, dependencies,
// versions and omission flags are generated and validated by code.
package aggregation

import (
	"encoding/json"

	"github.com/N0rthHXD/dmemd/internal/artifact"
	"github.com/N0rthHXD/dmemd/internal/ingest"
)

// Target is the artifact aggregation target shared with the dependency model.
// Bucket, topic and key are generated by code; the model never chooses a layer
// or target.
type Target = artifact.Target

// InputRef is one bounded lower-layer input selected for aggregation.
type InputRef = artifact.InputRef

// Request is the complete bounded aggregation input. InputCount is the number
// of eligible lower-layer inputs before truncation.
type Request struct {
	Target     Target     `json:"target"`
	Inputs     []InputRef `json:"inputs"`
	InputCount int        `json:"input_count"`
	Truncated  bool       `json:"truncated"`
}

// Result is the tolerant parsed aggregation body. Title, dependencies, version
// and stale state are generated by code from the target and inputs.
type Result struct {
	Title   string            `json:"title,omitempty"`
	Content string            `json:"content"`
	Payload json.RawMessage   `json:"payload,omitempty"`
	Usage   ingest.ModelUsage `json:"-"`
}
